/* Driver 2: bFindCollisionPoint (BCOLLIDE.C) */
#define FIXEDH(a) (((a) + 2048) >> 12)
void bFindCollisionPoint(CDATA2D *body, CRET2D *collisionResult)
{
    int lower, upper;
    int i, k, besti, bestk;
    int sign, sign0, sign1, smallest;
#define cd (&body[i ^ 1])

    besti = 0;
    bestk = 0;
    sign = 0;

    smallest = body[0].limit[0] + 1;

    i = 1;
    do {
        k = 1;
        do {
            upper = body[i].limit[k] - body[i].dist[k];
            lower = body[i].dist[k] + body[i].limit[k];

            if (smallest > upper) {
                smallest = upper;
                besti = i;
                bestk = k;
                sign = (i == 1) ? 1 : -1;
            }

            if (smallest > lower) {
                smallest = lower;
                besti = i;
                bestk = k;
                sign = (i == 1) ? -1 : 1;
            }

            k--;
        } while (k != -1);

        i--;
    } while (i != k);

    i = besti;

    if (cd->axis[0].vx * body[i].axis[bestk].vx + cd->axis[0].vz * body[i].axis[bestk].vz + 2048 > -1)
        sign0 = -sign;
    else
        sign0 = sign;

    if (cd->axis[1].vx * body[i].axis[bestk].vx + cd->axis[1].vz * body[i].axis[bestk].vz + 2048 > -1)
        sign1 = -sign;
    else
        sign1 = sign;

    collisionResult->hit.vx = cd->x.vx + FIXEDH(cd->axis[0].vx * cd->length[0] * sign0 + cd->axis[1].vx * cd->length[1] * sign1);
    collisionResult->hit.vz = cd->x.vz + FIXEDH(cd->axis[0].vz * cd->length[0] * sign0 + cd->axis[1].vz * cd->length[1] * sign1);

    collisionResult->penetration = smallest;

    if (i != 0)
        sign = -sign;

    collisionResult->surfNormal.vx = body[i].axis[bestk].vx * sign;
    collisionResult->surfNormal.vy = 0;
    collisionResult->surfNormal.vz = body[i].axis[bestk].vz * sign;
}
#undef FIXEDH
#undef cd

/* ---------------- bFindCollisionTime (src/pilot/bFindCollisionTime.c) ---------------- */
/* Driver 2: bFindCollisionTime */
int bFindCollisionTime(CDATA2D *cd, CRET2D *collisionResult)
{
    int hit;
    int i, q;
    int time, step;
    int neverfree;
    CDATA2D original[2];

    hit = 1;
    neverfree = 1;
    time = 4096;
    step = 2048;

    for (q = 1; q != -1; q--) {
        original[q].x.vx = cd[q].x.vx;
        original[q].x.vz = cd[q].x.vz;
        original[q].theta = cd[q].theta;
        for (i = 1; i != -1; i--) {
            original[q].limit[i] = cd[q].limit[i];
            original[q].dist[i] = cd[q].dist[i];
        }
    }

    i = 7;
    do {
        for (q = 1; q != -1; q--) {
            cd[q].vel.vx >>= 1;
            cd[q].vel.vz >>= 1;
            cd[q].avel >>= 1;

            if (hit) {
                cd[q].x.vx -= cd[q].vel.vx;
                cd[q].x.vz -= cd[q].vel.vz;
                cd[q].theta -= cd[q].avel;
            } else {
                cd[q].x.vx += cd[q].vel.vx;
                cd[q].x.vz += cd[q].vel.vz;
                cd[q].theta += cd[q].avel;
            }
        }

        if (hit) {
            time -= step;
        } else {
            time += step;
            neverfree = 0;
        }

        hit = bcollided2d(cd);

        if (i != 0)
            step >>= 1;

        i--;
    } while (i != -1);

    if (hit == 0) {
        for (q = 1; q != -1; q--) {
            cd[q].x.vx += cd[q].vel.vx;
            cd[q].x.vz += cd[q].vel.vz;
            cd[q].theta += cd[q].avel;
        }
        time += step;
        bcollided2d(cd);
    } else if (neverfree) {
        for (q = 1; q != -1; q--) {
            cd[q].x.vx = original[q].x.vx;
            cd[q].x.vz = original[q].x.vz;
            cd[q].theta = original[q].theta;
            bcollided2d(cd);
        }
        time = 4096;
    }

    collisionResult->neverfree = neverfree;

    return time;
}

/* ---------------- func_0003FAE8 (src/pilot/func_0003FAE8.c) ---------------- */
void func_0003FAE8(CAR_DATA *cp, signed char zone, int damage, unsigned char flag)
{
    int *dp;

    dp = &cp->damage[zone];
    if (cp == car_data) {
        D_000C6F00[0] = 1;
        damage = (damage * *(int *)&D_000977B0 + 0x800) >> 12;
    }
    if (cp->hndType == 1) {
        switch (*(int *)&D_00096870) {
        case 1:
            damage = damage * 12 / 16;
            break;
        case 2:
            damage = damage * 7 / 16;
            break;
        }
    }
    if (flag == 0)
        cp->totalDamage += damage;
    *dp += damage;
    if (*dp >= 0x1000)
        *dp = 0xFFF;

    switch (zone) {
    case 0: zone = 1; break;
    case 1: zone = 0; break;
    case 3: zone = 4; break;
    case 4: zone = 3; break;
    default: zone = -1; break;
    }
    if (zone != -1) {
        dp = &cp->damage[zone];
        damage >>= 1;
        if (*dp < damage) {
            if (flag == 0)
                cp->totalDamage += damage - *(unsigned short *)dp;
            *dp = damage;
        }
    }
    if (cp->totalDamage < 0)
        cp->totalDamage = 0x7FFF;
}

/* ---------------- func_0003FC98 (src/pilot/func_0003FC98.c) ---------------- */
int func_0003FC98(OBJ *p, VECTOR *v, int speed, unsigned char *q)
{
    VECTOR dir;
    VECTOR side;
    int fwd, lat;
    int dirn;
    char flag;

    if (speed < 0x1000)
        return 0;

    dir.vx = p->m[0][2];
    dir.vy = p->m[1][2];
    dir.vz = p->m[2][2];
    fwd = (dir.vx * v->vx + dir.vy * v->vy + dir.vz * v->vz + 0x800) >> 12;
    side.vx = p->m[0][0];
    side.vy = p->m[1][0];
    side.vz = p->m[2][0];
    lat = (side.vx * v->vx + side.vy * v->vy + side.vz * v->vz + 0x800) >> 12;

    if (lat > 0) {
        if (fwd < 0x105) {
            if (fwd >= -0x103)
                dirn = 2;
            else
                dirn = 3;
        } else
            dirn = 1;
    } else {
        if (fwd < 0x105) {
            if (fwd >= -0x103)
                dirn = 5;
            else
                dirn = 4;
        } else
            dirn = 0;
    }

    if (p->type == 0) {
        speed = ((speed / 350 + 0x200) * 3) / 8;
        if (speed >= 0x478)
            speed = 0x477;
    } else {
        speed = ((speed / 400 + 0x400) * 7) / 8;
    }

    flag = 1;
    if (p->type == 0x17)
        flag = *q != 0;
    else if (p->type == 0 || *q == 0 || D_00098950[p->type - 1].f5 == 0 || D_00098950[*q - 1].f5 == 0)
        flag = 0;

    func_0003FAE8(p, dirn, speed, flag);
    return 1;
}

